parameters.text:
=From: {{ $json.fromName }} <{{ $json.fromEmail }}>
Subject: {{ $json.subject }}

{{ $json.body }}

---
Signature to use: {{ $("Config").item.json.cfg_signature }}
Booking link (only include if non-empty): {{ $("Config").item.json.cfg_bookingLink }}

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "isCustomerInquiry": {
      "type": "boolean",
      "description": "True only if a real person (prospect, client, or partner) is writing to the business and expects a response."
    },
    "category": {
      "type": "string",
      "enum": [
        "sales_inquiry",
        "support",
        "scheduling",
        "partnership",
        "personal",
        "spam",
        "other"
      ]
    },
    "priority": {
      "type": "string",
      "enum": [
        "high",
        "normal",
        "low"
      ]
    },
    "needsHuman": {
      "type": "boolean",
      "description": "True if the reply needs pricing, commitments, account-specific facts, a complaint/dispute, legal/financial matters, or anything you are unsure about."
    },
    "confidence": {
      "type": "number",
      "description": "0 to 1. How confident you are that replyDraft can be sent as-is with no human edits."
    },
    "summary": {
      "type": "string",
      "description": "One sentence: what the sender wants."
    },
    "reasoning": {
      "type": "string",
      "description": "One short sentence explaining category, priority and needsHuman."
    },
    "replyDraft": {
      "type": "string",
      "description": "Plain-text reply body, no subject line, signed with the provided signature. Empty string if isCustomerInquiry is false."
    }
  },
  "required": [
    "isCustomerInquiry",
    "category",
    "priority",
    "needsHuman",
    "confidence",
    "summary",
    "reasoning",
    "replyDraft"
  ]
}

parameters.text:
={{ $json.priority === "high" ? "🔴" : "🟠" }} <b>Email needs you</b> ({{ $json.category }} · {{ $json.priority }})

<b>From:</b> {{ ($json.fromName + " <" + $json.fromEmail + ">").replace(/[<>&]/g, m => ({"<":"&lt;",">":"&gt;","&":"&amp;"})[m]) }}
<b>Subject:</b> {{ $json.subject.replace(/[<>&]/g, m => ({"<":"&lt;",">":"&gt;","&":"&amp;"})[m]) }}
<b>Why:</b> {{ ($json.aiReasoning || "").replace(/[<>&]/g, m => ({"<":"&lt;",">":"&gt;","&":"&amp;"})[m]) }}
{{ $json.createDraft ? "\n📝 Draft reply saved in Gmail." : "" }}
<a href="https://mail.google.com/mail/u/0/#all/{{ $json.threadId }}">Open in Gmail</a>
